# Explicit phrases where nominal conversion alone can invert or obscure the obligation.
PHRASES={
'clear concern expression':'People can clearly express their health concern',
'appropriate self-help guidance':'People can obtain appropriate self-help guidance',
'available alternative services':'Alternative services remain available',
'relevant decision alternatives':'Relevant decision alternatives are available',
'avoidance of unnecessary testing':'Unnecessary investigation testing is avoided',
'uninterrupted essential care':'Essential care continues without interruption',
'dignified assistance':'Assistance respects the person’s dignity',
'no autonomous authority':'Automated advice does not confer autonomous decision authority',
'non-authoritative assurance findings':'Assurance findings remain explicitly non-authoritative',
'upstream failure propagation':'The propagation of upstream failures can be identified',
'reproducible analysis inputs':'Analysis inputs can be reproduced',
'complete release gate':'Evidence release obeys the applicable authorisation and completeness policy',
'durable in-flight work':'In-flight work remains durable',
}
def improved_nominal(s):
 words=s.split();last=words[-1]
 if s.lower() in PHRASES:return PHRASES[s.lower()]
 # Preserve substantive negative constraints.
 if s.lower().startswith('no '):return s[3:]+' is prevented'
 for key,pred in PREDICATES.items():
  if last.lower()==key.lower() and len(words)>1:
   obj=' '.join(words[:-1])
   # Predicates with the nominal retained need no extra singularisation.
   plural=obj.split()[-1].lower().endswith('s') and not obj.lower().endswith(('access','process','status','loss','awareness','readiness','correctness'))
   if plural and not pred.startswith(('options','goals','advice','findings','alternatives','arrangements','content','propagation','services','direction','information','gaps','criteria','disagreements','feedback','loss','interruptions','inputs','leakage','output')):
    pred=re.sub(r'^is\b','are',pred);pred=re.sub(r'^has\b','have',pred);pred=re.sub(r'^retains\b','retain',pred);pred=re.sub(r'^receives\b','receive',pred)
   return obj+' '+pred
 # Use established adjective qualification where the nominal is not an action.
 for adj,pred in [('Correct','is correct'),('Current','is current'),('Available','is available'),('Relevant','is relevant'),('Clear','is clear'),('Explicit','is explicit'),('Visible','is visible'),('Appropriate','is appropriate'),('Required','is available when required'),('Authorised','is authorised'),('Approved','is approved'),('Valid','is valid'),('Minimum Necessary','is limited to the necessary scope'),('Consistent','is consistent'),('Meaningful','is meaningful'),('Recorded','is recorded'),('Defined','is defined'),('Verified','is verified'),('Controlled','is controlled')]:
  if s.lower().startswith(adj.lower()+' '):
   obj=s[len(adj)+1:];plural=obj.split()[-1].endswith('s') and not obj.endswith(('access','status','process'))
   return obj+(' '+pred.replace('is ','are ',1) if plural else ' '+pred)
 return original_nominal(s)
original_nominal=de_nominal
# Existing nominal conversion has useful action and quality predicates.
def de_nominal(s):
 initial=original_nominal(s)
 return improved_nominal(s) if initial.endswith(' is supported') else initial
